-- MesaPOS · PRE-VUELO de la publicación de caja/turnos. SOLO LECTURA (un único SELECT, no escribe nada).
-- Ejecutar en el proyecto que se va a publicar (producción: solo con aprobación del dueño, antes de cualquier migración).
-- No referencia columnas opcionales de forma estática: funciona aunque 03/04/07b aún no estén aplicadas (muestra n/a).
-- Cada fila: comprobación | valor | qué se espera. Compartir el resultado completo con Codex.
with
cols as (select table_name t, column_name c from information_schema.columns where table_schema='public'),
trg as (select c.relname t, g.tgname n from pg_trigger g join pg_class c on c.oid=g.tgrelid join pg_namespace s on s.oid=c.relnamespace where s.nspname='public' and not g.tgisinternal),
fn as (select p.proname n from pg_proc p join pg_namespace s on s.oid=p.pronamespace where s.nspname='public'),
tbl as (select table_name t from information_schema.tables where table_schema='public'),
rls as (select c.relname t, c.relrowsecurity r from pg_class c join pg_namespace s on s.oid=c.relnamespace where s.nspname='public' and c.relkind='r')
select * from (
 select 1 o, '03 estados separados: ventas.estado_pago y pagado_at' k, (exists(select 1 from cols where t='ventas' and c='estado_pago') and exists(select 1 from cols where t='ventas' and c='pagado_at'))::text v, 'true antes de 08 (si es false: aplicar 03 antes; 08 la necesita)' e
 union all select 2, '04 reserva Point: pagos_point.clave_idempotencia / referencia_externa / detalle', (select count(*) from cols where t='pagos_point' and c in ('clave_idempotencia','referencia_externa','detalle'))::text, '3'
 union all select 3, '04b aislamiento: triggers en pagos_point (≥2)', (select count(*) from trg where t='pagos_point')::text, '≥ 2 (04b) + pagos_point_bloquea_venta (07c)'
 union all select 4, '07b: aprobaciones_operacion, intentos_login, eventos_seguridad', (select count(*) from tbl where t in ('aprobaciones_operacion','intentos_login','eventos_seguridad'))::text, '3'
 union all select 5, '07b: usuarios.pin_hash', exists(select 1 from cols where t='usuarios' and c='pin_hash')::text, 'true'
 union all select 6, '07c: cobrar_venta_manual y editar_comanda_venta', (select count(*) from fn where n in ('cobrar_venta_manual','editar_comanda_venta'))::text, '2'
 union all select 7, '07c: trigger pagos_point_bloquea_venta', exists(select 1 from trg where n='pagos_point_bloquea_venta')::text, 'true'
 union all select 8, '08 ya aplicada? (tablas turnos)', (select count(*) from tbl where t in ('cobros_turno','movimientos_caja','cierres_turno','cierres_turno_medios','turno_eventos'))::text, '0 antes de aplicar 08; 5 después'
 union all select 9, '08: columnas nuevas ya presentes', (select count(*) from cols where (t='aperturas_caja' and c in ('modelo','fecha_apertura','cerrada_por')) or (t='ventas' and c='turno_id') or (t='pagos_point' and c='medio_reportado'))::text, '0 antes; 5 después'
 union all select 10, 'RLS cerrada (07/07a) en ventas / usuarios', coalesce((select r::text from rls where t='ventas'),'?')||' / '||coalesce((select r::text from rls where t='usuarios'),'?'), 'false / false si 07 NO está aplicada (Fase A); true / true tras 07a y 07'
 union all select 11, 'aperturas_caja ABIERTAS (turnos antiguos a cerrar con el flujo actual antes de publicar)', (case when exists(select 1 from cols where t='aperturas_caja' and c='estado') then (xpath('/row/c/text()', query_to_xml('select count(*) c from public.aperturas_caja where estado=''abierta''', false, true, '')))[1]::text else 'n/a (columna ausente)' end), '0 en la ventana de publicación'
 union all select 12, 'aperturas_caja abiertas sin empresa_id', (case when exists(select 1 from cols where t='aperturas_caja' and c='estado') and exists(select 1 from cols where t='aperturas_caja' and c='empresa_id') then (xpath('/row/c/text()', query_to_xml('select count(*) c from public.aperturas_caja where estado=''abierta'' and empresa_id is null', false, true, '')))[1]::text else 'n/a (columna ausente)' end), '0'
 union all select 13, 'ventas sin cobrar (estado_pago pendiente o sin_identificar)', (case when exists(select 1 from cols where t='ventas' and c='estado_pago') then (xpath('/row/c/text()', query_to_xml('select count(*) c from public.ventas where estado_pago in (''pendiente'',''sin_identificar'')', false, true, '')))[1]::text else 'n/a (03 no aplicada: no existe estado_pago)' end), 'anotar; 0 de hoy en la ventana'
 union all select 14, 'cobros Point ACTIVOS (reservado, created, at_terminal)', (case when exists(select 1 from cols where t='pagos_point' and c='estado') then (xpath('/row/c/text()', query_to_xml('select count(*) c from public.pagos_point where estado in (''reservado'',''created'',''at_terminal'')', false, true, '')))[1]::text else 'n/a (columna ausente)' end), '0 en la ventana de publicación'
 union all select 15, 'ventas pagadas como "Point" (histórico; no se reclasifica)', (case when exists(select 1 from cols where t='ventas' and c='estado_pago') and exists(select 1 from cols where t='ventas' and c='metodo_pago') then (xpath('/row/c/text()', query_to_xml('select count(*) c from public.ventas where metodo_pago=''Point'' and estado_pago=''pagado''', false, true, '')))[1]::text else 'n/a (03 no aplicada)' end), 'anotar'
 union all select 16, 'default de ventas.metodo_pago', coalesce((select column_default from information_schema.columns where table_schema='public' and table_name='ventas' and column_name='metodo_pago'),'(sin default)'), 'anotar: en pruebas es ''Débito''; el POS envía '''' al crear'
 union all select 17, 'ventas sin empresa_id', (case when exists(select 1 from cols where t='ventas' and c='empresa_id') then (xpath('/row/c/text()', query_to_xml('select count(*) c from public.ventas where empresa_id is null', false, true, '')))[1]::text else 'n/a (columna ausente)' end), '0'
 union all select 18, 'negocios (empresas)', (case when exists(select 1 from tbl where t='empresas') then (xpath('/row/c/text()', query_to_xml('select count(*) c from public.empresas', false, true, '')))[1]::text else 'n/a' end), 'anotar'
 union all select 19, 'cierres_caja existentes (histórico, no se modifica)', (case when exists(select 1 from tbl where t='cierres_caja') then (xpath('/row/c/text()', query_to_xml('select count(*) c from public.cierres_caja', false, true, '')))[1]::text else 'n/a' end), 'anotar; debe ser idéntico después'
 union all select 20, 'BLOQUEARÍAN el cierre: comandas sin entregar (pendiente/en_proceso/listo) NO archivadas de cocina', (case when exists(select 1 from cols where t='ventas' and c='cocina_archivada_at') and exists(select 1 from cols where t='ventas' and c='estado_pago') then (xpath('/row/c/text()', query_to_xml('select count(*) c from public.ventas where estado in (''pendiente'',''en_proceso'',''listo'') and cocina_archivada_at is null', false, true, '')))[1]::text else 'n/a (03 no aplicada)' end), '0 para poder cerrar el primer turno; el histórico listo se archiva con 06 (corte aprobado por el dueño)'
 union all select 21, '…de ellas, creadas hace más de 1 día', (case when exists(select 1 from cols where t='ventas' and c='cocina_archivada_at') and exists(select 1 from cols where t='ventas' and c='estado_pago') then (xpath('/row/c/text()', query_to_xml('select count(*) c from public.ventas where estado in (''pendiente'',''en_proceso'',''listo'') and cocina_archivada_at is null and created_at < now() - interval ''1 day''', false, true, '')))[1]::text else 'n/a (03 no aplicada)' end), 'idealmente 0; si no, el dueño decide: entregar/cobrar o archivar con corte'
 union all select 22, 'BLOQUEARÍAN el cierre: ventas sin cobrar (estado_pago pendiente) NO archivadas, de cualquier fecha', (case when exists(select 1 from cols where t='ventas' and c='cocina_archivada_at') and exists(select 1 from cols where t='ventas' and c='estado_pago') then (xpath('/row/c/text()', query_to_xml('select count(*) c from public.ventas where estado_pago = ''pendiente'' and cocina_archivada_at is null', false, true, '')))[1]::text else 'n/a (03 no aplicada)' end), '0; las antiguas no se ocultan: se resuelven o se archivan con corte aprobado'
 union all select 23, 'BLOQUEARÍAN el cierre del turno: ventas con medio sin identificar creadas desde la apertura', (case when exists(select 1 from cols where t='ventas' and c='cocina_archivada_at') and exists(select 1 from cols where t='ventas' and c='estado_pago') then (xpath('/row/c/text()', query_to_xml('select count(*) c from public.ventas where estado_pago = ''sin_identificar'' and cocina_archivada_at is null', false, true, '')))[1]::text else 'n/a (03 no aplicada)' end), 'anotar (solo cuentan las creadas dentro del turno)'
) q order by o;
